# مراجعة الشروح الشاملة، الدفعة 2 (2026-11-25): python3 data/gharib/audit/batch2.py
import json
S={
'D15':('أصاب عمّارًا جنابةٌ في سفر ولم يجد الماء، فتمرّغ في التراب ظنًّا أن التيمّم للجنابة يعمّ الجسد كالغسل، فعلّمه ﷺ أن التيمّم يكفي فيه الوجه والكفّان. قال ابن حجر: «فتمرّغت… أي تقلّبت، وكأنّ عمّارًا استعمل القياس في هذه المسألة؛ لأنه لما رأى أن التيمّم إذا وقع بدل الوضوء وقع على هيئة الوضوء، رأى أن التيمّم عن الغسل يقع على هيئة الغسل».','فتح الباري لابن حجر 1/444'),
'A12':('قال النووي: «أما العفاف والعفّة فهو التنزّه عمّا لا يُباح والكفّ عنه، والغنى هنا غنى النفس، والاستغناء عن الناس وعمّا في أيديهم».','شرح النووي على مسلم 17/41'),
'V07':('«أثبته»: داوم عليه. قال النووي: «هذا دليل على استحباب المحافظة على الأوراد، وأنها إذا فاتت تُقضى».','شرح النووي على مسلم 6/27'),
'KN36':('«الجريد»: قال ابن الأثير: «الجريدة: السعفة، وجمعها جريد»؛ أي أغصان النخل.','النهاية في غريب الحديث لابن الأثير 1/257'),
'DN08':('«نزحوا البئر»: أخذوا ماءها كله. قال ابن الأثير: «النزح… البئر التي أُخذ ماؤها، يقال: نزحتُ البئر». و«الراحلة»: قال: «البعير القوي على الأسفار والأحمال».','النهاية في غريب الحديث لابن الأثير 5/40 و2/209'),
'HB03':('«حِجر الكعبة»: قال ابن الأثير: «الحِجر بالكسر: اسم الحائط المستدير إلى جانب الكعبة الغربي».','النهاية في غريب الحديث لابن الأثير 1/341'),
'X23':('قال النووي: «هذه الأحاديث مبيّنة ما كان عليه ﷺ من الشفقة على أمته، والاعتناء بمصالحهم… وأنه إنما يكون دعاؤه عليه رحمةً وكفّارةً وزكاةً ونحو ذلك إذا لم يكن أهلًا للدعاء عليه والسبّ واللعن ونحوه، وكان مسلمًا». و«صلاة» هنا: رحمة.','شرح النووي على مسلم 16/150–151'),
}
d={c['id']:c for c in json.load(open('public/cards.json'))['cards']}
K=[]
for i,(t,s) in S.items():
    c=dict(d[i]); assert not c.get('sharh'); c['sharh']=dict(text=t,source=s); K.append(c)
json.dump({'cards':K,'quiz':[]},open('data/gharib/audit/batch2.json','w'),ensure_ascii=False,indent=1)
print(len(K))
